#pragma once

#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

#include <libbsa/archive.hpp>
#include <libbsa/export.hpp>
#include <libbsa/result.hpp>

namespace libbsa
{

  /// Stable compatibility warning identifiers returned by validation reports.
  ///
  /// Codes are intended for programmatic branching. Human-readable messages may
  /// change as diagnostics improve, but these identifiers remain the public
  /// compatibility contract for warning categories.
  enum class compatibility_warning_code
  {
    compressed_sound_payload,
    bsa_embedded_name_compatibility_risk,
    target_family_mismatch,
  };

  /// Severity for compatible-but-noteworthy validation warnings.
  ///
  /// `advisory` warnings describe information a consumer may want to display.
  /// `risky` warnings describe archives that can be valid while still carrying a
  /// known interoperability risk.
  enum class compatibility_warning_severity
  {
    advisory,
    risky,
  };

  /// Fatal archive validation diagnostic.
  ///
  /// `code` is the stable public error category. `message` is diagnostic text for
  /// humans and should not be treated as a stable machine-readable value.
  struct validation_diagnostic
  {
    /// Stable public error category for the validation failure.
    error_code code;

    /// Human-readable diagnostic text for logs or UI display.
    std::string message;
  };

  /// Compatibility warning emitted for a valid but noteworthy archive condition.
  ///
  /// Warnings keep stable code and severity values separate from human-readable
  /// text. `archive_path` is present only when the warning applies to one entry.
  struct compatibility_warning
  {
    /// Stable public warning category.
    compatibility_warning_code code;

    /// Warning severity for display, sorting, or caller escalation.
    compatibility_warning_severity severity;

    /// Human-readable warning text for logs or UI display.
    std::string message;

    /// Optional normalized archive path when the warning applies to a specific entry.
    std::optional<std::string> archive_path;
  };

  /// Caller-selected validation policy.
  ///
  /// Options are intentionally small: callers may assert the expected archive
  /// family, expected variant, and whether every entry should be extracted during
  /// validation.
  struct validation_options
  {
    /// Expected top-level archive family, when the caller knows it in advance.
    std::optional<archive_type> expected_type;

    /// Expected archive variant, when the caller knows it in advance.
    std::optional<archive_variant> expected_variant;

    /// True to validate entry extraction in addition to archive structure.
    bool validate_entry_extractability{false};

    /// Maximum declared stored or decoded bytes extracted per entry during validation.
    ///
    /// This limit applies only when `validate_entry_extractability` is true. Entries
    /// above the limit become structured validation diagnostics instead of causing
    /// validation to allocate archive-controlled payload sizes.
    std::uint64_t max_extractability_entry_bytes{64U * 1024U * 1024U};
  };

  /// Structured validation result for an archive host path.
  ///
  /// Reports expose only overall validity, optional archive metadata, fatal
  /// diagnostics, and compatibility warnings. They do not expose parser offsets,
  /// record indexes, chunk indexes, entry listings, or extraction bytes.
  ///
  /// Thread-safety: reports are independent values after return; see
  /// `docs/thread-safety.md` for validation result inspection rules.
  struct validation_report
  {
    /// True when no fatal validation errors were found.
    bool valid{false};

    /// Archive metadata when it could be parsed safely.
    std::optional<archive_metadata> metadata;

    /// Fatal validation diagnostics that make the archive invalid.
    std::vector<validation_diagnostic> errors;

    /// Compatible-but-noteworthy archive conditions found during validation.
    std::vector<compatibility_warning> warnings;

    /// Returns true when the report represents a valid archive.
    [[nodiscard]] LIBBSA_API bool is_valid() const noexcept;
  };

  /// Validates an archive host path and returns structured diagnostics.
  ///
  /// Result-level failures are reserved for call/setup failures such as invalid
  /// or unreadable host paths. Inspectable archive problems are reported inside
  /// `validation_report::errors` so callers can display all available diagnostics.
  ///
  /// Thread-safety: validation uses no global mutable state, so independent calls
  /// may run concurrently subject to the host filesystem.
  [[nodiscard]] LIBBSA_API result<validation_report> validate_archive(std::string_view host_path,
                                                                      validation_options options = {});

} // namespace libbsa

#pragma once

#include <stdexcept>
#include <string>
#include <utility>
#include <variant>

namespace libbsa
{

  /// Stable error categories returned by libbsa public APIs.
  ///
  /// The enum intentionally stays small and format-neutral so callers can branch
  /// on durable categories without depending on parser implementation details.
  enum class error_code
  {
    unsupported,
    invalid_argument,
    not_found,
    io_error,
    format_error,
  };

  /// Structured error value returned by result-producing libbsa APIs.
  ///
  /// `code` is stable and suitable for tests and programmatic handling. `message`
  /// is diagnostic text for humans and should not be compared exactly by tests.
  struct error
  {
    error_code code;
    std::string message;
  };

  /// C++20-compatible result type used by libbsa public APIs.
  ///
  /// This is a deliberately small expected-like type. I/O and format failures are
  /// represented as `error` values. Calling `value()` on an error result or
  /// `error()` on a successful result is a programmer mistake and throws
  /// `std::logic_error`.
  template <typename T>
  class result
  {
  public:
    /// Creates a successful result containing `value`.
    result(T value) : storage_(std::move(value)) {}

    /// Creates a failed result containing `err`.
    result(error err) : storage_(std::move(err)) {}

    /// Returns true when this result contains a value.
    [[nodiscard]] bool has_value() const noexcept
    {
      return std::holds_alternative<T>(storage_);
    }

    /// Returns true when this result contains a value.
    [[nodiscard]] explicit operator bool() const noexcept { return has_value(); }

    /// Returns the contained value, or throws if this result contains an error.
    T &value() &
    {
      if (!has_value())
      {
        throw std::logic_error("libbsa::result has no value");
      }
      return std::get<T>(storage_);
    }

    /// Returns the contained value, or throws if this result contains an error.
    const T &value() const &
    {
      if (!has_value())
      {
        throw std::logic_error("libbsa::result has no value");
      }
      return std::get<T>(storage_);
    }

    /// Returns the contained value, or throws if this result contains an error.
    T &&value() &&
    {
      if (!has_value())
      {
        throw std::logic_error("libbsa::result has no value");
      }
      return std::move(std::get<T>(storage_));
    }

    /// Returns the contained error, or throws if this result contains a value.
    [[nodiscard]] const libbsa::error &error() const
    {
      if (has_value())
      {
        throw std::logic_error("libbsa::result has no error");
      }
      return std::get<libbsa::error>(storage_);
    }

  private:
    std::variant<T, libbsa::error> storage_;
  };

  /// C++20-compatible result specialization for operations that return no value.
  template <>
  class result<void>
  {
  public:
    /// Creates a successful void result.
    result() noexcept = default;

    /// Creates a failed void result containing `err`.
    result(error err) : error_(std::move(err)), has_value_(false) {}

    /// Returns true when this result represents success.
    [[nodiscard]] bool has_value() const noexcept { return has_value_; }

    /// Returns true when this result represents success.
    [[nodiscard]] explicit operator bool() const noexcept { return has_value(); }

    /// Throws if this result contains an error.
    void value() const
    {
      if (!has_value())
      {
        throw std::logic_error("libbsa::result<void> has no value");
      }
    }

    /// Returns the contained error, or throws if this result represents success.
    [[nodiscard]] const libbsa::error &error() const
    {
      if (has_value())
      {
        throw std::logic_error("libbsa::result<void> has no error");
      }
      return error_;
    }

  private:
    libbsa::error error_{error_code::unsupported, {}};
    bool has_value_{true};
  };

} // namespace libbsa

#pragma once

#include <cstddef>
#include <cstdint>
#include <memory>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <vector>

#include <libbsa/export.hpp>
#include <libbsa/result.hpp>

namespace libbsa
{

  /// Supported top-level Bethesda archive container families.
  enum class archive_type
  {
    bsa,
    ba2,
  };

  /// Public archive variants known to libbsa.
  ///
  /// The same metadata field represents supported BSA and BA2 format families
  /// without changing the public reader shape as archive coverage expands.
  enum class archive_variant
  {
    tes3,
    tes4,
    fallout4,
    starfield,
  };

  /// Compression representation selected by archive metadata for an entry.
  ///
  /// The values describe observable archive payload encoding without exposing the
  /// private codec libraries used to implement each mode.
  enum class entry_compression
  {
    none,
    deflate,
    lz4_frame,
    lz4_block,
  };

  /// BA2-specific archive-level metadata exposed when `archive_metadata::type` is `archive_type::ba2`.
  ///
  /// Starfield BA2 revisions append raw header fields after the common `BTDX`/subtype header.
  /// These fields are intentionally version-gated optionals so Fallout 4 archives can distinguish
  /// "field absent" from a Starfield field that is present with a zero value.
  struct ba2_archive_metadata
  {
    /// Raw Starfield v2+ header field conventionally named `Unknown1` in current references.
    std::optional<std::uint32_t> starfield_unknown1;

    /// Raw Starfield v2+ header field conventionally named `Unknown2` in current references.
    std::optional<std::uint32_t> starfield_unknown2;

    /// Raw Starfield v3 compression method field; method `3` selects raw LZ4 block payloads.
    std::optional<std::uint32_t> compression_method;
  };

  /// Per-chunk BA2 texture payload metadata exposed for dependency-light inspection.
  ///
  /// Offsets are archive-absolute and sizes describe the stored chunk bytes plus the decoded
  /// payload bytes. The compression route is a libbsa-owned value so callers never depend on
  /// private codec or texture-analysis libraries.
  struct texture_chunk_metadata
  {
    /// Archive-absolute byte offset of this chunk's stored payload.
    std::uint64_t payload_offset;

    /// Stored byte count in the archive; zero-sized stored metadata is represented as raw chunks by parsers.
    std::uint32_t stored_size;

    /// Decoded chunk byte count before DDS header reconstruction.
    std::uint32_t raw_size;

    /// First mip level covered by this chunk, inclusive.
    std::uint16_t start_mip;

    /// Last mip level covered by this chunk, inclusive.
    std::uint16_t end_mip;

    /// Compression route selected from archive metadata for this chunk.
    entry_compression compression;
  };

  /// Dependency-light BA2 texture metadata attached only to texture archive entries.
  ///
  /// The format field stores the raw numeric graphics format identifier used by DDS DXT10
  /// metadata, preserving the value without exposing platform or analyzer types. For texture
  /// entries, `entry_metadata::raw_size` is the consumer-visible reconstructed DDS size including
  /// its header; archive payload sizes remain on the per-chunk metadata below.
  struct texture_metadata
  {
    /// Texture width in pixels.
    std::uint32_t width;

    /// Texture height in pixels.
    std::uint32_t height;

    /// Number of mip levels described by the texture record.
    std::uint32_t mip_count;

    /// Raw numeric DDS DXT10 graphics format identifier.
    std::uint32_t dxgi_format;

    /// Texture array element count represented independently from cubemap state.
    std::uint32_t array_size;

    /// True when the BA2 record represents cubemap texture data.
    bool is_cubemap;

    /// Raw BA2 texture record byte with currently unknown Bethesda-specific semantics.
    std::uint8_t unknown_tex;

    /// Raw BA2 cubemap/array field preserved for compatibility evidence.
    std::uint16_t cube_maps_raw;

    /// Chunk layout and compression metadata in archive order unless a later parser documents otherwise.
    std::vector<texture_chunk_metadata> chunks;
  };

  /// Archive-level metadata exposed by an opened reader.
  ///
  /// The structure is intentionally limited to stable public fields: container
  /// type, archive variant/version, raw archive flags, file count, the default
  /// compression behavior advertised by the archive family, and optional
  /// format-family metadata that remains dependency-light.
  struct archive_metadata
  {
    archive_type type;
    archive_variant variant;
    std::uint32_t version;
    std::uint32_t archive_flags;
    std::uint32_t file_count;
    entry_compression default_compression;
    std::optional<ba2_archive_metadata> ba2;
  };

  /// Entry-level metadata exposed for lookup, listing, and extraction.
  ///
  /// `path` is the canonical normalized lookup key. `original_path` preserves the
  /// archive-derived display spelling joined with `/` separators, independent of
  /// host filesystem path rules. `payload_offset` is always an archive-absolute
  /// byte offset for every archive variant; format-specific relative offsets stay
  /// inside parser internals and fixture manifests.
  struct entry_metadata
  {
    std::string path;
    std::string original_path;
    std::uint64_t raw_size;
    std::uint64_t stored_size;
    std::uint64_t payload_offset;
    std::uint64_t archive_hash;
    entry_compression compression;
    std::uint32_t record_flags;
    bool has_embedded_name;
    std::uint32_t embedded_name_prefix_size;
    /// Optional texture metadata populated only for BA2 DX10 texture entries.
    std::optional<texture_metadata> texture;
  };

  /// Synchronous sink used by archive extraction APIs.
  ///
  /// Implementations must return the number of bytes accepted from `bytes`. The
  /// extractor treats partial acceptance as `error_code::io_error` so callers
  /// never observe ambiguous partial-success extraction.
  ///
  /// Thread-safety: sinks are caller-owned; concurrent extraction requires
  /// distinct sinks or caller-owned synchronization for intentionally shared
  /// output state. See `docs/thread-safety.md`.
  class LIBBSA_API payload_sink
  {
  public:
    virtual ~payload_sink() = default;

    /// Writes a chunk of payload bytes and returns the accepted byte count.
    virtual result<std::size_t> write(std::span<const std::byte> bytes) = 0;
  };

  /// Options controlling a bulk extraction call.
  ///
  /// The default is intentionally serial. Pass a positive value greater than one
  /// to opt into parallel extraction of independent entries.
  ///
  /// Thread-safety: options are copied into the extraction call; see
  /// `docs/thread-safety.md` for caller mutation rules.
  struct bulk_extract_options
  {
    /// Number of worker threads to use; `0` is invalid and never means "auto".
    std::uint32_t worker_count{1U};
  };

  /// A single archive path requested from `archive_reader::extract_entries`.
  struct bulk_extract_request
  {
    /// Archive path to extract, using the same lookup rules as `archive_reader::extract`.
    std::string path;
  };

  /// Factory used by bulk extraction to create sinks for unique requested paths.
  ///
  /// Implementations must return a distinct sink for every successful `create`
  /// call. `archive_reader::extract_entries` coalesces duplicate exact request
  /// paths before extraction, so duplicate result records mirror the first
  /// occurrence and do not trigger additional `create` calls. When
  /// `bulk_extract_options::worker_count` is greater than one, `create` may be
  /// called concurrently for independent unique paths and the returned sinks may
  /// be written on worker threads. libbsa does not call user factory or sink
  /// methods while holding an internal mutex.
  ///
  /// Thread-safety: caller-owned factories must protect shared state and return
  /// distinct sinks for concurrent unique-path extraction.
  class LIBBSA_API bulk_extract_sink_factory
  {
  public:
    virtual ~bulk_extract_sink_factory() = default;

    /// Creates the sink that will receive the payload for the unique request `path`.
    ///
    /// Returning an error records a per-entry failure and does not abort
    /// independent sibling entries.
    virtual result<std::unique_ptr<payload_sink>> create(std::string_view path, const entry_metadata &entry) = 0;
  };

  /// Per-request result record returned by `archive_reader::extract_entries`.
  ///
  /// Thread-safety: result records are independent values after the caller-owned
  /// result vector is no longer being mutated.
  struct bulk_extract_entry_result
  {
    /// Requested archive path in the same order supplied by the caller.
    std::string path;

    /// Entry metadata when lookup succeeded before extraction.
    std::optional<entry_metadata> entry;

    /// Per-entry failure, if lookup, sink creation, or extraction failed.
    std::optional<error> failure;

    /// Returns true when this record completed without a per-entry failure.
    [[nodiscard]] bool succeeded() const noexcept { return !failure.has_value(); }
  };

  /// Public archive reader for supported Bethesda archive files.
  ///
  /// Use `open()` for fallible construction. A successfully opened reader exposes
  /// archive metadata, deterministic entry listings, canonical path lookup, and
  /// synchronous extraction for the archive variants implemented by libbsa.
  ///
  /// Thread-safety: independently opened readers may be used concurrently; one
  /// reader may run concurrent const extraction calls only with distinct sinks as
  /// described in `docs/thread-safety.md`.
  class archive_reader
  {
  public:
    /// Attempts to open an archive from a host path string.
    ///
    /// Empty host paths return `error_code::invalid_argument`, missing or
    /// unreadable files return `error_code::io_error`, unsupported archive bytes
    /// return `error_code::unsupported`, and malformed supported archives return
    /// `error_code::format_error`.
    static LIBBSA_API result<archive_reader> open(std::string_view host_path);

    /// Returns archive-level metadata for a successfully opened archive.
    [[nodiscard]] LIBBSA_API result<archive_metadata> metadata() const;

    /// Returns deterministic entry metadata sorted by canonical archive path.
    [[nodiscard]] LIBBSA_API result<std::vector<entry_metadata>> entries() const;

    /// Finds metadata for a normalized archive path if it exists.
    ///
    /// Invalid archive path syntax is reported as `error_code::invalid_argument`;
    /// valid missing paths return an empty optional so lookup can distinguish
    /// absence from malformed caller input.
    [[nodiscard]] LIBBSA_API result<std::optional<entry_metadata>> find(std::string_view path) const;

    /// Returns whether a valid archive path exists in the opened archive.
    [[nodiscard]] LIBBSA_API result<bool> contains(std::string_view path) const;

    /// Extracts an entry by archive path into a synchronous caller-owned sink.
    [[nodiscard]] LIBBSA_API result<void> extract(std::string_view path, payload_sink &sink) const;

    /// Extracts an entry into a bounded in-memory byte vector convenience result.
    [[nodiscard]] LIBBSA_API result<std::vector<std::byte>> extract_bytes(std::string_view path) const;

    /// Extracts multiple request records into caller-created unique-path sinks.
    ///
    /// Setup failures such as an unopened reader or `worker_count == 0` fail the
    /// outer result. Lookup, sink-creation, and extraction failures are recorded
    /// on the corresponding request-order result record so independent sibling
    /// entries can still complete. Duplicate exact request paths are coalesced:
    /// the first occurrence owns lookup, sink creation, and extraction, while
    /// later duplicate result records preserve their request path and mirror the
    /// first occurrence's entry and failure outcome.
    [[nodiscard]] LIBBSA_API result<std::vector<bulk_extract_entry_result>> extract_entries(
        std::span<const bulk_extract_request> requests,
        bulk_extract_sink_factory &sink_factory,
        bulk_extract_options options = {}) const;

  private:
    struct state;

    explicit archive_reader(archive_metadata metadata);

    std::shared_ptr<const state> state_;
  };

} // namespace libbsa

#include <catch2/catch_test_macros.hpp>

#include <libbsa/libbsa.hpp>

#include <detail/bethesda_hash.hpp>

#include <algorithm>
#include <array>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

#include <nlohmann/json.hpp>

namespace
{

  struct validation_archive_case
  {
    std::string_view file_name;
    libbsa::archive_type expected_type;
    libbsa::archive_variant expected_variant;
  };

  std::filesystem::path generated_archive_dir()
  {
    return std::filesystem::path{LIBBSA_SOURCE_DIR} / "tests" / "fixtures" / "generated" / "archives";
  }

  std::filesystem::path generated_source_dir()
  {
    return std::filesystem::path{LIBBSA_SOURCE_DIR} / "tests" / "fixtures" / "generated" / "source";
  }

  std::filesystem::path compatibility_matrix_path()
  {
    return std::filesystem::path{LIBBSA_SOURCE_DIR} / "tests" / "fixtures" / "generated" / "compatibility_matrix.json";
  }

  std::filesystem::path validation_test_dir()
  {
    auto path = std::filesystem::temp_directory_path() / "libbsa_validation_api_tests";
    std::filesystem::create_directories(path);
    return path;
  }

  std::filesystem::path unique_output_path(std::string_view stem, std::string_view extension)
  {
    static std::atomic_uint64_t counter{0};
    auto path = validation_test_dir() / (std::string{stem} + "-" +
                                         std::to_string(counter.fetch_add(1, std::memory_order_relaxed)) +
                                         std::string{extension});
    std::filesystem::remove(path);
    return path;
  }

  std::vector<std::byte> bytes_from_text(std::string_view text)
  {
    std::vector<std::byte> bytes;
    bytes.reserve(text.size());
    for (const char ch : text)
    {
      bytes.push_back(static_cast<std::byte>(static_cast<unsigned char>(ch)));
    }
    return bytes;
  }

  /// Appends a little-endian UInt16 value to a synthetic binary fixture buffer.
  void append_u16_le(std::vector<std::byte> &bytes, std::uint16_t value)
  {
    bytes.push_back(static_cast<std::byte>(value & 0xFFU));
    bytes.push_back(static_cast<std::byte>((value >> 8U) & 0xFFU));
  }

  /// Appends a little-endian UInt32 value to a synthetic binary fixture buffer.
  void append_u32_le(std::vector<std::byte> &bytes, std::uint32_t value)
  {
    for (unsigned shift = 0; shift < 32U; shift += 8U)
    {
      bytes.push_back(static_cast<std::byte>((value >> shift) & 0xFFU));
    }
  }

  /// Appends a little-endian UInt64 value to a synthetic binary fixture buffer.
  void append_u64_le(std::vector<std::byte> &bytes, std::uint64_t value)
  {
    for (unsigned shift = 0; shift < 64U; shift += 8U)
    {
      bytes.push_back(static_cast<std::byte>((value >> shift) & 0xFFU));
    }
  }

  /// Appends raw ASCII bytes, including embedded NULs when present in the view.
  void append_ascii(std::vector<std::byte> &bytes, std::string_view value)
  {
    for (const char ch : value)
    {
      bytes.push_back(static_cast<std::byte>(static_cast<unsigned char>(ch)));
    }
  }

  class temp_file_cleanup final
  {
  public:
    /// Owns cleanup for a temporary validation fixture path.
    explicit temp_file_cleanup(std::filesystem::path path) : path_{std::move(path)} {}

    /// Best-effort cleanup keeps sparse validation fixtures from surviving failed tests.
    ~temp_file_cleanup()
    {
      std::error_code ignored;
      std::filesystem::remove(path_, ignored);
    }

  private:
    std::filesystem::path path_;
  };

  nlohmann::json read_json_file(const std::filesystem::path &path)
  {
    std::ifstream stream{path};
    REQUIRE(stream.is_open());
    return nlohmann::json::parse(stream);
  }

  libbsa::error_code error_code_from_matrix(std::string_view value)
  {
    if (value == "format_error")
    {
      return libbsa::error_code::format_error;
    }
    if (value == "unsupported")
    {
      return libbsa::error_code::unsupported;
    }
    FAIL("unknown compatibility matrix expected_error: " << value);
    return libbsa::error_code::format_error;
  }

  void require_valid_archive(std::string_view host_path,
                             libbsa::archive_type expected_type,
                             libbsa::archive_variant expected_variant,
                             libbsa::validation_options options = {})
  {
    auto validated = libbsa::validate_archive(host_path, options);
    REQUIRE(validated.has_value());

    const auto &report = validated.value();
    CHECK(report.valid);
    CHECK(report.is_valid());
    CHECK(report.errors.empty());
    REQUIRE(report.metadata.has_value());
    CHECK(report.metadata->type == expected_type);
    CHECK(report.metadata->variant == expected_variant);
  }

  void require_validation_setup_error(std::string_view host_path, libbsa::error_code expected_code)
  {
    auto validated = libbsa::validate_archive(host_path);

    REQUIRE_FALSE(validated.has_value());
    CHECK(validated.error().code == expected_code);
  }

  void require_malformed_open_report(std::string_view file_name, libbsa::error_code expected_code)
  {
    const auto archive_path = generated_archive_dir() / std::string{file_name};

    auto opened = libbsa::archive_reader::open(archive_path.string());
    REQUIRE_FALSE(opened.has_value());
    CHECK(opened.error().code == expected_code);

    auto validated = libbsa::validate_archive(archive_path.string());
    REQUIRE(validated.has_value());
    const auto &report = validated.value();
    CHECK_FALSE(report.valid);
    CHECK_FALSE(report.is_valid());
    CHECK_FALSE(report.metadata.has_value());
    REQUIRE(report.errors.size() == 1U);
    CHECK(report.errors.front().code == expected_code);
  }

  bool report_has_error_code(const libbsa::validation_report &report, libbsa::error_code expected_code)
  {
    return std::any_of(report.errors.begin(), report.errors.end(), [expected_code](const libbsa::validation_diagnostic &error)
                       { return error.code == expected_code; });
  }

  void require_matrix_open_report(const nlohmann::json &row)
  {
