 'error_code refs': /error_code::\w+/g,
 'validate_archive refs': /validate_archive/g,
 'validation_report refs': /validation_report/g,
 'compat warnings': /compatibility_warning/g,
 'COV-GAP-001': /COV-GAP-001/g,
 'result-level tests': /result-level|setup errors|invalid_argument|io_error|not_found|format_error|unsupported/g
};
function walk(dir, out=[]){ if(!fs.existsSync(dir)) return out; for(const ent of fs.readdirSync(dir,{withFileTypes:true})){ const p=path.join(dir,ent.name); if(ent.isDirectory()) walk(p,out); else out.push(p);} return out; }
const files=roots.flatMap(r=>walk(r)).filter(p=>/\.(hpp|cpp|md|txt|cmake)$/.test(p));
for(const [name,rx0] of Object.entries(patterns)){
 const counts={}; let total=0;
 for(const f of files){ let text; try{text=fs.readFileSync(f,'utf8')}catch{continue}; const m=text.match(rx0); if(m){counts[f]=m.length; total+=m.length;} }
 const sorted=Object.keys(counts).sort((a,b)=>counts[b]-counts[a]||a.localeCompare(b)).slice(0,20);
 console.log(`## ${name}: ${Object.keys(counts).length} files, ${total} refs`);
 for(const f of sorted) console.log(`${String(counts[f]).padStart(4)} ${f.replaceAll('\\','/')}`);
 console.log('');
